import { viewApi as api, viewWorkspace as workspace } from './api.js';
import { state, activeDataset, scopedDatasets } from './state.js';
import { esc, num, unitName, icon, button, badge, status, notice, empty, heading, field, input, textarea, select, formFooter, jsonView, table, timeText } from './components.js';
export const financialFields = [['revenue', '营业收入'], ['cost', '营业成本'], ['cash_flow', '经营现金流'], ['net_profit', '净利润'], ['assets', '总资产'], ['liabilities', '总负债'], ['inventory', '库存金额'], ['equity_begin', '期初净资产'], ['equity_end', '期末净资产'], ['sales_volume', '销量（统一单位）'], ['production_volume', '产量（相同单位）'], ['manufacturing_cost', '制造费用'], ['rd_expense', '研发费用'], ['lithium_price', '锂价 / 元每吨'], ['industry_volatility', '行业波动率 / 比值']];
export function periodRow(p = {}, index = 0) { return `<tr data-period-row><td><input aria-label="季度 ${index + 1}" name="period" value="${esc(p.period ?? '')}" placeholder="2025-Q1" pattern="20[0-9]{2}-Q[1-4]" required></td>${financialFields.map(([key, label], i) => `<td class="${i >= 7 ? 'extra-column' : ''}"><input aria-label="${esc(label)} ${index + 1}" name="${key}" type="number" step="any" ${key === 'revenue' || key === 'cost' ? 'required min="0"' : ''} value="${esc(p[key] ?? '')}"></td>`).join('')}<td>${button(icon('close'), 'remove-period', 'icon-button', 'aria-label="删除此季度行"')}</td></tr>`; }
export function datasetEditor(d) {
    const p = d?.payload ?? {}, persisted = Boolean(d?.id);
    state.cache.editor = d;
    return `<form id="dataset-editor" data-id="${esc(d?.id ?? '')}" data-version="${d?.version ?? 0}"><div class="form-grid">${field('企业名称', input('company', p.company, 'required maxlength="200" ' + (persisted ? 'readonly' : '')), persisted ? '企业归属贯穿报告、证据与行动，不能通过修订更换；其他企业请新建数据集' : '')}${field('数据集名称', input('name', p.name, 'required maxlength="200"'))}${field('金额单位', select('amount_unit', { yuan: '元', wan: '万元', yi: '亿元' }, p.amount_unit ?? state.user.preferences.amount_unit), '保存时统一为元；锂价始终为元/吨')}${field('输入期间口径', select('basis', { standalone_quarter: '单季度实际值', year_to_date: '年初累计值 → 转单季度' }, 'standalone_quarter'))}${field('原始来源地址', input('source_url', p.source_url, 'type="url" placeholder="https://…"'))}${field('口径备注', input('notes', p.notes, 'maxlength="2000"'))}</div>
 <div class="row-between section-heading"><h3>季度财务数据</h3><label class="check-label"><input type="checkbox" id="extra-fields"> 展开产销与补充指标</label></div><div class="table-scroll editor-table" role="region" tabindex="0" aria-label="财务录入表，可横向滚动"><table><thead><tr><th>季度</th>${financialFields.map(([, label], i) => `<th class="${i >= 7 ? 'extra-column' : ''}">${esc(label)}</th>`).join('')}<th></th></tr></thead><tbody id="period-rows">${(p.periods ?? [{}]).map(periodRow).join('')}</tbody></table></div>
 <div class="micro-row">${button(icon('plus') + ' 添加季度', 'add-period', 'text-button')}<span>收入与成本必填；其他未知值留空。产销量使用相同单位并在备注注明，不跟随金额单位缩放。</span></div>${formFooter('预览校验与差异')}</form>`;
}
export function qualityPanel(q) {
    const labels = { ...Object.fromEntries(financialFields), source_url: '原始来源地址', period: '季度', source_kind: '输入来源类型' };
    const info = q.findings.filter((f) => f.severity !== 'warning').length;
    return `<div class="quality-strip"><span>${q.closed_quarters} 个已结束季度</span><span>${esc(q.field_coverage.period ?? '最新季度')}：${q.field_coverage.present} / ${q.field_coverage.total} 个补充字段</span>${badge(q.warning_count + ' 项结构警告', q.warning_count ? 'warm' : 'neutral')}${badge(info + ' 项字段与来源提示', info ? 'warm' : 'neutral')}</div>${notice('输入来自用户提供，未独立核验；0项结构警告不表示各季度字段完整或内容真实。')}${q.findings.length ? table(['季度', '核对事项', '对应字段'], q.findings.map((f) => [f.code === 'MISSING_SOURCE' ? '整个数据集' : esc(f.period), badge(f.severity === 'warning' ? '结构警告' : '资料或字段提示', f.severity === 'warning' ? 'warm' : 'neutral') + ' ' + esc(f.message), esc(f.fields.map((k) => labels[k] ?? k).join('、'))])) : notice('结构规则未发现异常；仍应核对原始资料与各期输入。')}`;
}
// Shift the JSON number's decimal spelling only; binary division can introduce
// visible tails (0.29 yuan / 10000) or underflow during a pre-save value check.
function previewNumber(value, places = 0) {
    const match = String(value).match(/^(-?)(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/);
    if (!match)
        return '无法展示，请核对技术详情';
    const [, sign, whole, fraction = '', exponent = '0'] = match, digits = whole + fraction, position = whole.length + Number(exponent) - places;
    if (position <= -20)
        return `${sign}${whole}${fraction ? '.' + fraction : ''}e${Number(exponent) - places}`;
    let left = position > 0 ? digits.slice(0, position).padEnd(position, '0') : '0', right = position > 0 ? digits.slice(position) : '0'.repeat(-position) + digits;
    left = left.replace(/^0+(?=\d)/, '').replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    right = right.replace(/0+$/, '');
    return sign + left + (right ? '.' + right : '');
}
function readableImportPreview(p) {
    const declared = p.import_context?.input_amount_unit ?? p.dataset.input_amount_unit;
    const unit = ['yuan', 'wan', 'yi'].includes(declared) ? declared : 'yuan';
    const units = { sales_volume: '原填数量', production_volume: '原填数量', lithium_price: '元/吨', industry_volatility: '比值' };
    const shown = (row, key) => ({ value: row[key] == null ? '未提供' : previewNumber(row[key], units[key] ? 0 : { yuan: 0, wan: 4, yi: 8 }[unit]), unit: units[key] ?? unitName(unit) });
    const value = (row, key) => shown(row, key).value;
    const rows = (row, fields, group) => `<div class="table-scroll preview-values" role="region" tabindex="0" aria-label="${esc(row.period)} ${esc(group)}：将保存的中文字段与数值"><table><thead><tr><th scope="col">指标</th><th scope="col">将保存值</th><th scope="col">单位</th></tr></thead><tbody>${fields.map(([key, label]) => `<tr data-preview-field="${esc(key)}"><td>${esc(label)}</td><td>${esc(value(row, key))}</td><td>${esc(shown(row, key).unit)}</td></tr>`).join('')}</tbody></table></div>`;
    if (!p.dataset.periods.length)
        return '';
    return `<section class="import-readable" aria-label="逐季度核对将保存的数据"><h3>逐季度核对将保存的数据</h3><p class="micro">下表显示将保存的单季度值，金额展示为${esc(unitName(unit))}，保存时统一为元。${p.import_context?.input_basis === 'year_to_date' ? '年初累计已转为单季度；这里不是原文件累计行值。' : ''}未提供与数值 0 分开显示。</p><p class="micro">产销量按原填数量显示，不随金额单位缩放；具体数量单位请结合口径备注和原始资料核对。${p.dataset.notes ? `口径备注：${esc(p.dataset.notes)}` : '口径备注：未填写，数量单位未记录。'}</p>${p.dataset.periods.map((row, index) => `<details class="preview-quarter" data-preview-period="${esc(row.period)}" ${index === 0 ? 'open' : ''}><summary><strong>${esc(row.period)}</strong><span>营业收入 ${esc(value(row, 'revenue'))} ${esc(shown(row, 'revenue').unit)} · 营业成本 ${esc(value(row, 'cost'))} ${esc(shown(row, 'cost').unit)} · 经营现金流 ${esc(value(row, 'cash_flow'))}${row.cash_flow == null ? '' : ' ' + esc(shown(row, 'cash_flow').unit)}</span></summary>${rows(row, financialFields.slice(0, 7), '基础指标')}<details class="preview-supplement"><summary>产销与补充指标（${financialFields.length - 7} 项）</summary>${rows(row, financialFields.slice(7), '产销与补充指标')}</details></details>`).join('')}</section>`;
}
export function stageView(row) {
    const p = row.payload;
    return `<div class="stack"><div class="row-between"><div><h3>${esc(p.dataset.company)} · ${esc(p.dataset.name)}</h3><p class="muted">${p.dataset.periods.length} 个季度 · 归一化金额：元 · 尚未写入财务库</p></div>${badge('待确认', 'warm')}</div>${importSummary(p)}${qualityPanel(p.quality)}${readableImportPreview(p)}${p.diff.length ? `<h3>将保存的变更</h3>${table(['字段路径', '原值', '新值'], p.diff.map((d) => [esc(d.path), esc(d.before ?? '空'), esc(d.after ?? '空')]))}` : notice(p.target_id ? '与当前数据没有字段差异；确认仍会记录一次修订。' : '这是一份新的数据集；预览确认前不会生成诊断。')}
<details><summary>查看标准化后的完整数据</summary>${jsonView(p.dataset)}</details><p class="form-error" role="alert"></p><div class="form-footer">${button('返回继续编辑', 'stage-back', 'secondary')}${button('确认保存 ' + icon('check'), 'commit-stage', 'primary', `data-id="${esc(row.id)}"`)}</div></div>`;
}
export async function dataPage() {
    const d = activeDataset();
    const editor = d ? datasetEditor(d) : empty(scopedDatasets().length ? '请选择一份经营数据' : '还没有经营数据', scopedDatasets().length ? '从左侧选择企业，再核对来源、期间口径与修订记录。' : '从自己的报表开始。工作区没有预置公司、行情或演示数据。', button(icon('plus') + ' 新建数据集', 'new-dataset', 'primary'));
    return heading('经营数据', '导入、核对、修订。每次诊断使用独立的数据快照。', button(icon('upload') + ' 导入文件', 'import-dialog') + button(icon('plus') + ' 新建数据集', 'new-dataset', 'primary')) +
        `<div class="collection-layout"><aside class="collection"><h3>数据集 <span>${scopedDatasets().length}</span></h3>${scopedDatasets().map(x => `<button class="collection-item ${x.id === state.active ? 'selected' : ''}" data-action="select-dataset" data-id="${esc(x.id)}"><strong>${esc(x.payload.company)}</strong><span>${esc(x.payload.name)}</span><small>${x.payload.periods.length} 个季度 · ${esc(x.payload.periods.at(-1)?.period)}</small></button>`).join('') || '<p class="muted">暂无数据</p>'}</aside><section class="panel data-panel">${d ? `<div class="section-heading row-between"><h2>${esc(d.payload.company)}</h2><div class="tools">${button(icon('eye') + ' 质量', 'data-quality')}${button(icon('clock') + ' 修订记录', 'data-revisions')}${button(icon('network'), 'data-lineage', 'icon-button', 'aria-label="查看指标血缘"')}${button(icon('download'), 'export-dataset', 'icon-button', 'aria-label="导出数据"')}${button(icon('trash'), 'delete-dataset', 'icon-button danger-text', `data-id="${esc(d.id)}" data-version="${d.version}" aria-label="删除数据集"`)}</div></div>` : ''}${editor}</section></div>`;
}
export function importForm(draft = {}) { if (draft.target_id && !scopedDatasets().some(d => d.id === draft.target_id))
    throw new Error('原导入目标已不在当前范围，请重新打开导入并明确选择目标。'); if (draft.identity_id !== undefined && (draft.identity_id !== state.identity || draft.active_dataset !== state.active))
    throw new Error('导入上下文已变化，请重新打开当前范围的导入窗口。'); return `<form id="import-file-form" class="stack" data-target-versions="${esc(JSON.stringify(draft.target_versions ?? Object.fromEntries(scopedDatasets().map(d => [d.id, d.version]))))}">${field('导入目标', select('target_id', { '': '新建独立数据集', ...Object.fromEntries(scopedDatasets().map(d => [d.id, `修订：${d.payload.company} · ${d.payload.name}（v${d.version}）`])) }, draft.target_id ?? ''), '选择已有数据集可保留跟踪与行动关联；企业名称必须一致')}${field('修订方式（新建时忽略）', select('merge_mode', { merge: '合并季度：保留文件未包含的历史季度', replace: '替换全部季度：删除文件未包含的历史季度' }, draft.merge_mode ?? 'merge'))}${field('所属企业', input('company', draft.company ?? activeDataset()?.payload.company ?? '', 'required maxlength="200"'))}<div class="form-grid">${field('文件金额单位', select('amount_unit', { yuan: '元', wan: '万元', yi: '亿元' }, draft.amount_unit ?? state.user.preferences.amount_unit), '不可从数值猜测单位；数量不缩放，锂价始终为元/吨')}${field('文件期间口径', select('basis', { standalone_quarter: '单季度', year_to_date: '年初累计 → 单季度' }, draft.basis ?? 'standalone_quarter'), '累计文件必须包含同年上一季度累计值；不会用库内单季度值替代')}</div>${draft.company !== undefined ? notice('企业、单位和期间口径已保留；请重新选择修改后的文件。') : ""}<label class="upload-box">${icon('upload')}<strong>选择财务文件</strong><span>CSV / XLSX / JSON · 最大 2 MB</span><input type="file" name="file" accept=".csv,.xlsx,.json" required></label><p class="micro">支持“季度/报告期、营业收入、营业成本、经营活动产生的现金流量净额、资产总计、负债合计”等表头。支持规范千分位与括号负数，仅行业波动率支持百分号。CSV 含逗号的数字须用双引号包裹。未知值留空，不用横线代替。不执行公式；XLSX 只接受单工作表。JSON 企业和单位以文件为准。</p>${notice('合并按完整季度行替换：同季度文件中未提供的补充字段会变为缺失；不会悄悄沿用旧值。修订保留原数据集名称、来源地址与备注，保存前请检查差异。', 'warm')}<a href="/api/import/template" download>下载空白 CSV 表头 ${icon('download')}</a>${formFooter('读取并预览')}</form>`; }
export function importSummary(p) { const c = p.import_context; if (!c)
    return ''; return `<section class="stack"><h3>${c.mode === 'new' ? '新建独立数据集' : c.mode === 'merge' ? '合并到已有数据集' : '替换已有数据集全部季度'}${p.target_id ? ` · 当前 v${p.target_version} → v${p.target_version + 1}` : ''}</h3><p class="micro">文件：${esc(c.filename)} · 文件金额单位：${esc(unitName(c.input_amount_unit))} · ${c.input_basis === 'year_to_date' ? '累计值先转为单季度，再合并' : '单季度值'} · 保存金额统一为元</p>${table(['季度变更', '期间'], [['新增', esc(c.added.join('、') || '无')], ['整行替换（含空值）', esc(c.replaced.join('、') || '无')], ['保留历史', esc(c.retained.join('、') || '无')], ['删除历史', esc(c.removed.join('、') || '无')]])}${c.removed.length ? notice('确认后将从当前数据中删除上述历史季度；历史修订仍可查阅。', 'warm') : ''}${c.normalizations.length ? `<details><summary>查看 ${c.normalizations.length} 项文件转换（表头/数字）</summary>${table(['文件行', '字段', '原值', '转换后', '规则'], c.normalizations.map((n) => [esc(n.row), esc(n.field), esc(n.source), esc(n.normalized), esc(n.rule)]))}</details>` : ''}</section>`; }
export async function evidencePage() {
    const result = await workspace('/evidence');
    state.cache.evidence = result.items;
    return heading('证据资料', '原始内容、适用范围与审阅意见分开保存。', button(icon('upload') + ' 上传文档', 'document-dialog') + button(icon('plus') + ' 添加资料', 'evidence-dialog', 'primary')) +
        `<div class="toolbar"><form id="evidence-search" class="search-form">${icon('search')}<input name="q" placeholder="检索原文中的指标、事项或来源" aria-label="检索证据" required><button class="secondary">检索</button></form>${button('公开资料搜索', 'public-search-dialog', 'secondary')}</div><div id="evidence-search-results"></div>
 <div class="panel flush">${result.items.length ? table(['资料', '适用范围', '审阅状态', '更新', ''], result.items.map((d) => [`<button class="title-button" data-action="evidence-detail" data-id="${esc(d.id)}">${icon('files')}<span><strong>${esc(d.payload.title)}</strong><small>${num(d.payload.text.length, 0)} 字符 · ${d.payload.source_url ? '已提供来源链接' : '未提供来源链接'}</small></span></button>`, `${esc(d.review.company || (d.review.global_scope ? '通用资料' : '范围未指定'))}<div class="tag-row">${d.review.tags.map((t) => badge(t)).join('')}</div>`, status(d.review.status) + (!d.eligible ? badge(d.excluded_reason === 'expired' ? '已过期' : '不参与检索', 'warm') : ''), timeText(d.updated_at), button('审阅', 'review-evidence', 'text-button', `data-id="${esc(d.id)}"`) + button(icon('trash'), 'delete-evidence', 'icon-button danger-text', `data-id="${esc(d.id)}" data-version="${d.version}" aria-label="删除资料"`)])) : empty('尚无证据资料', '添加文本、上传文档，或经确认获取公开来源。模型不会假装读过未提供的资料。', button('添加原始资料', 'evidence-dialog', 'primary'))}</div>`;
}
export function evidenceScope(company = activeDataset()?.payload.company ?? '', global = false) { return field('所属企业', input('company', company, 'maxlength="200"'), '填写企业；只有明确勾选下方选项，资料才对所有企业可用') + `<label class="check-label"><input name="global_scope" type="checkbox" ${global ? 'checked' : ''}> 作为通用资料，允许所有企业使用（请清空所属企业）</label>`; }
export function evidenceMetadataForm(d) { return `<form id="evidence-metadata-form" data-id="${esc(d.id)}" data-version="${d.version}" class="stack">${field('资料标题', input('title', d.payload.title, 'required maxlength="200"'))}${field('来源地址（用户维护）', input('source_url', d.payload.source_url, 'type="url" maxlength="1000"'))}${field('发布日期', input('published_at', d.payload.published_at, 'type="date"'))}${notice('只修改显示元数据；原文、获取来源和核验标签保持不变。')}${formFooter('保存元数据')}</form>`; }
export function evidenceForm() { return `<form id="evidence-form" class="stack">${field('资料标题', input('title', '', 'required maxlength="200"'))}<div class="form-grid">${field('来源地址', input('source_url', '', 'type="url" placeholder="https://…"'))}${field('发布日期', input('published_at', '', 'type="date"'))}</div>${field('原文内容', textarea('text', '', 'rows="9" minlength="20" maxlength="120000" required placeholder="粘贴原始材料；不会将其中的操作指令作为系统命令"'))}${evidenceScope()}${formFooter('保存原始资料')}</form>`; }
export function reviewEvidenceForm(d) { const p = d.review; return `<form id="evidence-review-form" data-id="${esc(d.id)}" data-version="${d.review_version}" class="stack"><h3>${esc(d.payload.title)}</h3><div class="form-grid">${evidenceScope(p.company, p.global_scope ?? false)}${field('有效截至', input('expires_at', p.expires_at, 'type="date"'))}${field('审阅结论', select('status', { unreviewed: '尚未审阅', accepted: '人工接受', rejected: '排除，不用于新任务' }, p.status))}${field('证据立场', select('stance', { context: '背景资料', supports: '支持某项判断', contradicts: '反向/反驳证据' }, p.stance))}</div>${field('主题标签（逗号分隔）', input('tags', p.tags.join('，')))}${field('审阅依据与适用边界', textarea('note', p.note, 'rows="4" maxlength="2000"'))}${notice('“人工接受”仅记录你的审阅意见，不是系统的事实认证；更改将使相关未执行计划失效。')}${formFooter('保存审阅记录')}</form>`; }
export async function memoryPage() {
    const result = await api('/memories');
    state.cache.memories = result.items;
    return heading('长期记忆', '只在批准的范围内使用。偏好不是企业事实。', button(icon('plus') + ' 添加记忆', 'memory-dialog', 'primary')) +
        `<div class="panel flush">${result.items.length ? table(['内容', '作用域', '有效期', '状态', ''], result.items.map((m) => { const p = m.payload; const expired = p.expires_at && p.expires_at < new Date().toISOString().slice(0, 10); return [`<strong>${esc(p.text)}</strong><small class="block">${esc({ preference: '偏好', fact: '用户声明事实', note: '研究备注' }[p.kind] ?? p.kind)}</small>`, esc(p.company || '所有企业') + '<small class="block">' + esc({ all: '所有角色', enterprise: '企业分析', investor: '投资研究', analyst: '财务分析', advisor: '顾问服务' }[p.role] ?? p.role) + '</small>', esc(p.expires_at ?? '未设置'), badge(expired ? '已过期' : p.approved ? '已批准' : '待批准', expired ? 'warm' : p.approved ? 'good' : 'neutral'), button(p.approved ? '撤回批准' : '批准使用', 'toggle-memory', 'text-button', `data-id="${esc(m.id)}"`) + button('编辑', 'edit-memory', 'text-button', `data-id="${esc(m.id)}"`) + button(icon('trash'), 'delete-memory', 'icon-button danger-text', `data-id="${esc(m.id)}" data-version="${m.version}" aria-label="删除记忆"`)]; })) : empty('尚未保存长期记忆', '由你决定记住什么、用于哪家企业，以及何时停止使用。', button('添加记忆', 'memory-dialog', 'primary'))}</div>`;
}
export function memoryForm(m = null) { const p = m?.payload ?? {}; return `<form id="memory-form" data-id="${esc(m?.id ?? '')}" data-version="${m?.version ?? 0}" class="stack">${field('要记住的内容', textarea('text', p.text, 'rows="4" required maxlength="1500"'))}<div class="form-grid">${field('记忆类型', select('kind', { preference: '偏好', fact: '用户声明事实（待核实）', note: '研究备注' }, p.kind ?? 'note'))}${field('作用企业', input('company', p.company ?? activeDataset()?.payload.company ?? ''))}${field('适用角色', select('role', { all: '所有角色', enterprise: '企业分析', investor: '投资研究', analyst: '财务分析', advisor: '顾问服务' }, p.role ?? 'all'))}${field('到期时间', input('expires_at', p.expires_at, 'type="date"'))}</div><label class="check-label"><input name="approved" type="checkbox" ${p.approved ? 'checked' : ''}> 允许在匹配的诊断任务中使用</label><p class="micro">撤回或删除会阻止新计划召回；已执行报告保留历史快照。相关会话及独立保存的计划/实验需分别清理，或删除整个账户。</p>${formFooter('保存记忆')}</form>`; }
export function revisionHistory(items) {
    return notice('恢复历史内容会创建新的修订，不会修改或抹除旧报告。') + items.slice().reverse().map((v) => {
        const valid = v.integrity_valid !== false;
        const changes = !valid ? notice('此修订完整性校验失败，未采用其内容、计算差异或提供恢复。请保留原记录并检查可信备份。', 'warm') :
            v.diff_available === false ? notice('相邻历史修订无法校验，未计算差异；本修订内容已通过完整性校验。', 'warm') :
                v.diff.length ? table(['路径', '原值', '新值'], v.diff.map((c) => [esc(c.path), esc(c.before), esc(c.after)])) : '<p>初始保存的内容或与上一修订无字段差异。</p>';
        return `<details><summary>修订 ${esc(v.version)} · ${timeText(v.created_at)}${valid ? '' : ' · 完整性异常'}</summary>${changes}${valid ? button('以此内容创建新修订', 'restore-revision', 'secondary', `data-revision="${esc(v.version)}"`) : ''}<p class="micro">${esc(v.content_hash)}</p>${v.import_receipt ? `<details><summary>本次导入处理回执</summary>${jsonView(v.import_receipt.payload)}<p class="micro">回执校验 ${esc(v.import_receipt.content_hash)}</p></details>` : notice('此修订没有导入处理回执；不能推定原文件或转换过程。')}</details>`;
    }).join('');
}
